"use strict";(self.webpackChunkdoc_adk_training_site=self.webpackChunkdoc_adk_training_site||[]).push([[1925],{6198:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>i,contentTitle:()=>s,default:()=>u,frontMatter:()=>l,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"module26-callbacks/lab-solution","title":"Lab Solution","description":"Goal","source":"@site/../training/module26-callbacks/lab-solution.md","sourceDirName":"module26-callbacks","slug":"/module26-callbacks/lab-solution","permalink":"/doc-adk-training/docs/module26-callbacks/lab-solution","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Lab Solution"}}');var r=t(4848),a=t(8453);const l={sidebar_position:3,title:"Lab Solution"},s="Lab 26 Solution: Building a Content Moderation Assistant",i={},c=[{value:"Goal",id:"goal",level:2},{value:"<code>content_moderator/agent.py</code>",id:"content_moderatoragentpy",level:3},{value:"Self-Reflection Answers",id:"self-reflection-answers",level:3}];function d(e){const n={code:"code",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"lab-26-solution-building-a-content-moderation-assistant",children:"Lab 26 Solution: Building a Content Moderation Assistant"})}),"\n",(0,r.jsx)(n.h2,{id:"goal",children:"Goal"}),"\n",(0,r.jsxs)(n.p,{children:["This file contains the complete code for the ",(0,r.jsx)(n.code,{children:"agent.py"})," script in the Content Moderation Assistant lab."]}),"\n",(0,r.jsx)(n.h3,{id:"content_moderatoragentpy",children:(0,r.jsx)(n.code,{children:"content_moderator/agent.py"})}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-python",children:'import hashlib\nimport os\nimport re\nimport logging\nfrom typing import Dict, Any, Optional\nfrom google.adk import Agent\nfrom google.adk.agents.callback_context import CallbackContext\nfrom google.adk.tools import ToolContext\nfrom google.adk.tools.base_tool import BaseTool\nfrom google.adk.models.llm_request import LlmRequest\nfrom google.adk.models.llm_response import LlmResponse\nfrom google.genai import types\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n# --- Configuration ---\nBLOCKED_WORDS = [\'unsafe\', \'offensive\']\n\n# --- Caching helper: key the cache by the CURRENT turn\'s user input ---\ndef _current_user_text(callback_context: CallbackContext) -> str:\n    """Extracts the text of the current turn\'s user message."""\n    user_content = callback_context.get_invocation_context().user_content\n    if not user_content or not user_content.parts:\n        return ""\n    return "".join(p.text or "" for p in user_content.parts)\n\ndef _cache_key(callback_context: CallbackContext) -> str:\n    """\n    Derives a cache key from the current user input, not a single global\n    slot. Without this, ANY cached response would be replayed for EVERY\n    subsequent question in the session, regardless of what was asked.\n    """\n    user_text = _current_user_text(callback_context)\n    digest = hashlib.md5(user_text.strip().lower().encode("utf-8")).hexdigest()\n    return f"cache:{digest}"\n\n# --- Callback 1: Caching (Check) ---\ndef before_agent_callback(callback_context: CallbackContext) -> Optional[types.Content]:\n    """Intercepts execution to check for a cached response for THIS input."""\n    key = _cache_key(callback_context)\n    cached_text = callback_context.state.get(key)\n    if cached_text:\n        print("\u26a1 [CACHE HIT] Returning saved result, skipping LLM.")\n        return types.Content(\n            parts=[types.Part(text=f"[CACHED]: {cached_text}")],\n            role="model"\n        )\n    return None\n\n# --- Callback 2: Caching (Save) ---\ndef after_agent_callback(callback_context: CallbackContext) -> None:\n    """Saves the final response to session state, keyed by the input that produced it."""\n    # Find the last model response in the session history\n    events = callback_context.session.events\n    for event in reversed(events):\n        if event.author != "user" and event.content:\n            response_text = event.content.parts[0].text\n            key = _cache_key(callback_context)\n            callback_context.state[key] = response_text\n            print("\ud83d\udcbe [CACHE SAVE] Result persisted to session state.")\n            break\n\n# --- Callback 3: Input Guardrail ---\ndef before_model_callback(\n    callback_context: CallbackContext,\n    llm_request: LlmRequest\n) -> Optional[LlmResponse]:\n    """Prevents inappropriate prompts from reaching the LLM."""\n    user_text = "".join([p.text for c in llm_request.contents for p in c.parts if p.text])\n    \n    for word in BLOCKED_WORDS:\n        if word in user_text.lower():\n            print(f"\ud83d\uded1 [GUARDRAIL] Blocked prompt containing: {word}")\n            return LlmResponse(\n                content=types.Content(\n                    parts=[types.Part(text="I\'m sorry, I cannot process offensive prompts.")],\n                    role="model"\n                )\n            )\n    return None\n\n# --- Callback 4: Output Filtering ---\ndef after_model_callback(\n    callback_context: CallbackContext,\n    llm_response: LlmResponse\n) -> Optional[LlmResponse]:\n    """Removes sensitive email addresses from the LLM response."""\n    if not llm_response.content or not llm_response.content.parts:\n        return None\n\n    original_text = llm_response.content.parts[0].text\n    if not original_text:\n        # The model\'s response may be a pure function call (e.g. deciding to\n        # invoke generate_text) with no text part to filter.\n        return None\n    # Simple email regex\n    redacted_text = re.sub(r\'\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Z|a-z]{2,}\\b\', \'[EMAIL_REDACTED]\', original_text)\n    \n    if redacted_text != original_text:\n        print("\ud83d\udee1\ufe0f [FILTER] Redacted PII from model response.")\n        # Return a modified copy of the response\n        return llm_response.model_copy(update={\n            "content": types.Content(parts=[types.Part(text=redacted_text)], role="model")\n        })\n    return None\n\n# --- Callback 5: Tool Validation ---\ndef before_tool_callback(\n    tool: BaseTool,\n    args: Dict[str, Any],\n    tool_context: ToolContext\n) -> Optional[Dict[str, Any]]:\n    """Validates tool arguments before execution."""\n    if tool.name == \'generate_text\':\n        count = args.get(\'word_count\', 0)\n        if count > 5000:\n            print(f"\u26a0\ufe0f [VALIDATION] Blocked tool call: word_count {count} is too high.")\n            return {\n                \'status\': \'error\', \n                \'message\': \'Word count exceeds the maximum limit of 5000.\'\n            }\n    return None\n\n# --- Callback 6: Tool Output Audit ---\ndef after_tool_callback(\n    tool: BaseTool,\n    args: Dict[str, Any],\n    tool_context: ToolContext,\n    tool_response: Dict[str, Any]\n) -> Optional[Dict[str, Any]]:\n    """Audits tool output and redacts blocked words as a defense-in-depth layer."""\n    if tool.name == \'generate_text\':\n        text = tool_response.get(\'text\', \'\')\n        if any(word in text.lower() for word in BLOCKED_WORDS):\n            print("\ud83d\udee1\ufe0f [AUDIT] Redacted blocked word from tool output.")\n            redacted = text\n            for word in BLOCKED_WORDS:\n                redacted = redacted.replace(word, \'***\')\n            return {**tool_response, \'text\': redacted}\n        print(f"\ud83d\udccb [AUDIT] Tool \'{tool.name}\' executed successfully.")\n    return None\n\n# --- Tools ---\ndef generate_text(topic: str, word_count: int) -> dict:\n    """Generates text on a topic."""\n    return {"status": "success", "text": f"A {word_count}-word essay on {topic}..."}\n\n# --- Agent Registration ---\nroot_agent = Agent(\n    name="secure_moderator",\n    model="gemini-3.5-flash",\n    instruction="You are a professional content assistant.",\n    tools=[generate_text],\n    before_agent_callback=before_agent_callback,\n    after_agent_callback=after_agent_callback,\n    before_model_callback=before_model_callback,\n    after_model_callback=after_model_callback,\n    before_tool_callback=before_tool_callback,\n    after_tool_callback=after_tool_callback\n)\n'})}),"\n",(0,r.jsx)(n.h3,{id:"self-reflection-answers",children:"Self-Reflection Answers"}),"\n",(0,r.jsxs)(n.ol,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.strong,{children:"What is the key difference between a callback and a plugin in the ADK? When would you choose one over the other?"})}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Answer:"})," The key difference lies in their scope and primary role. ",(0,r.jsx)(n.strong,{children:"Callbacks"})," are agent-specific, designed for control, modification, and implementing guardrails ",(0,r.jsx)(n.em,{children:"within a single agent's logic"}),". They can block or alter an agent's execution. ",(0,r.jsx)(n.strong,{children:"Plugins"})," are global (registered at the ",(0,r.jsx)(n.code,{children:"Runner"})," level), designed for observation and telemetry (metrics, logging, alerting) ",(0,r.jsx)(n.em,{children:"across all agents in an application"}),". Choose a callback to modify or block an agent's specific operations; choose a plugin to monitor behavior across the entire system without altering its logic."]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:(0,r.jsxs)(n.strong,{children:["Why does returning a ",(0,r.jsx)(n.code,{children:"types.Content"})," object from ",(0,r.jsx)(n.code,{children:"before_agent_callback"})," cause the agent to skip the LLM call entirely?"]})}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Answer:"})," Returning an object from a callback signals to the ADK framework to ",(0,r.jsx)(n.em,{children:"override"})," the default behavior. Since ",(0,r.jsx)(n.code,{children:"before_agent_callback"})," happens at the very beginning of the agent's lifecycle, returning a final ",(0,r.jsx)(n.code,{children:"Content"}),' object tells the framework "I already have the answer, you don\'t need to do any work." The ADK accepts this ',(0,r.jsx)(n.code,{children:"Content"})," as the final result and skips tool execution and LLM invocation, saving time and tokens. This is the core mechanism behind caching."]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.strong,{children:"How does using callbacks for guardrails and validation make an agent more reliable and safer to deploy in a production environment?"})}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Answer:"})," Callbacks significantly enhance reliability and safety by introducing deterministic, hard-coded checks for critical functionalities, reducing reliance on the LLM's non-deterministic reasoning. For instance, ",(0,r.jsx)(n.code,{children:"before_model_callback"})," can proactively prevent harmful input from reaching the LLM, and ",(0,r.jsx)(n.code,{children:"after_model_callback"})," can filter sensitive data (PII) from responses before they are exposed. Similarly, ",(0,r.jsx)(n.code,{children:"before_tool_callback"})," validates tool arguments, preventing runtime errors and ensuring tools are used correctly. This layered approach creates a more stable, secure, and predictable agent behavior in production."]}),"\n"]}),"\n"]}),"\n"]})]})}function u(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453:(e,n,t)=>{t.d(n,{R:()=>l,x:()=>s});var o=t(6540);const r={},a=o.createContext(r);function l(e){const n=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:l(e.components),o.createElement(a.Provider,{value:n},e.children)}}}]);